import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"단축키 설정","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/hotkeys-page.md","filePath":"ko-KR/user-guide/settings/hotkeys-page.md","lastUpdated":1787758874000}'),s={name:"ko-KR/user-guide/settings/hotkeys-page.md"};function a(n,o,i,c,d,g){return t(),r("div",null,[...o[0]||(o[0]=[l('<h1 id="단축키-설정" tabindex="-1">단축키 설정 <a class="header-anchor" href="#단축키-설정" aria-label="Permalink to &quot;단축키 설정&quot;">​</a></h1><p>단축키 설정 페이지에서는 Lertaro의 모든 전역 호출 키, 앱 내 탐색 단축키, 플러그인 액션 바로가기 및 프로세스 블랙리스트 규칙을 통합 관리합니다. 상단에는 <strong>전역</strong>, <strong>플러그인 액션</strong>, <strong>프로세스 블랙리스트</strong>의 3개 탭이 제공됩니다.</p><h2 id="_1-전역-global" tabindex="-1">1. 전역 (Global) <a class="header-anchor" href="#_1-전역-global" aria-label="Permalink to &quot;1. 전역 (Global)&quot;">​</a></h2><h3 id="전역-단축키-그룹" tabindex="-1">전역 단축키 그룹 <a class="header-anchor" href="#전역-단축키-그룹" aria-label="Permalink to &quot;전역 단축키 그룹&quot;">​</a></h3><ul><li><strong>퀵 검색 표시/숨기기</strong>: 전용 키 녹화 컨트롤. <strong>수식키 더블 클릭 모드</strong>(기본값 <code>Ctrl</code> 더블 클릭, <code>Alt</code>나 <code>Shift</code>로도 가능) 및 <strong>일반 조합키</strong>(예: <code>Alt+Space</code>, <code>Win+Space</code> 등)를 모두 지원합니다.</li><li><strong>전체 패널을 기본으로 열기</strong>: 체크박스(기본 비활성화). 켜면 전역 호출 단축키가 퀵 윈도우 대신 메인 윈도우를 열고 닫습니다. 이 방법으로 연 메인 윈도우만 다른 창보다 위에 표시되며, <strong>메인 윈도우 열기</strong>, 트레이 메뉴 또는 다른 진입점으로 열 때는 항상 위에 표시되지 않습니다.</li><li><strong>전체화면 앱 포커스 시에도 응답</strong>: 체크박스(기본 비활성화). 켜면 전체화면 게임이나 동영상 재생기가 활성화되어 있어도 단축키에 응답하며, 끄면 게임 플레이를 보호하기 위해 단축키를 통과시킵니다.</li><li><strong>퀵 점프 (Quick Jump)</strong>: 기본값 <code>Ctrl+G</code>. 파일 대화상자에서 최근 탐색했던 폴더로 즉시 이동합니다.</li></ul><h3 id="기능-키-그룹" tabindex="-1">기능 키 그룹 <a class="header-anchor" href="#기능-키-그룹" aria-label="Permalink to &quot;기능 키 그룹&quot;">​</a></h3><p>임의의 단일 키 또는 조합키를 지정할 수 있는 독립 녹화 컨트롤을 제공합니다.</p><ul><li><strong>다음 / 이전 항목 선택</strong>: 기본값 <code>Ctrl+N</code> / <code>Ctrl+P</code>(방향키 <code>↓</code> / <code>↑</code>와 동일).</li><li><strong>결과 이동 수식키</strong>: 기본값 <code>Ctrl</code>, 숫자키 <code>1</code>–<code>9</code>와 조합하여 즉시 실행.</li><li><strong>액션 메뉴 열기</strong>: 기본값 <code>Ctrl+O</code>(방향키 <code>→</code>와 동일).</li><li><strong>선택 항목으로 검색어 자동완성</strong>: 기본값 <code>Ctrl+Tab</code>.</li><li><strong>QuickLook 즉시 미리보기</strong>: 기본값 <code>Alt+P</code>.</li><li><strong>이전 / 다음 검색 기록어</strong>: 기본값 <code>Alt+Up</code> / <code>Alt+Down</code>.</li><li><strong>현재 검색 기록어 삭제</strong>: 기본값 <code>Ctrl+Delete</code>.</li><li><strong>메인 윈도우 열기</strong>: 기본값 <code>Ctrl+F</code>.</li><li><strong>LocalSend 창 열기</strong>: 기본값 <code>Ctrl+S</code>.</li><li><strong>창 고정 (항상 유지)</strong>: 기본값 <code>Ctrl+T</code>.</li><li><strong>퀵 패널 표시/숨기기</strong>: 기본값 <code>Ctrl+F2</code>.</li></ul><h3 id="퀵-내비게이션-마우스-트리거-그룹" tabindex="-1">퀵 내비게이션 마우스 트리거 그룹 <a class="header-anchor" href="#퀵-내비게이션-마우스-트리거-그룹" aria-label="Permalink to &quot;퀵 내비게이션 마우스 트리거 그룹&quot;">​</a></h3><ul><li><strong>빈 공간 좌클릭 더블클릭</strong>: 체크박스(기본 활성화). 바탕화면이나 탐색기 빈 공간 더블클릭 시 메뉴 표시.</li><li><strong>빈 공간 휠클릭</strong>: 체크박스(기본 활성화). 바탕화면, 탐색기 또는 파일 대화상자에서 휠클릭 시 메뉴 표시.</li></ul><h2 id="_2-플러그인-액션-plugin-actions" tabindex="-1">2. 플러그인 액션 (Plugin Actions) <a class="header-anchor" href="#_2-플러그인-액션-plugin-actions" aria-label="Permalink to &quot;2. 플러그인 액션 (Plugin Actions)&quot;">​</a></h2><p>각 플러그인이 등록한 전용 액션 단축키(예: 경로 복사 <code>Ctrl+Shift+C</code>, 잘라내기 <code>Ctrl+X</code>, 복사 <code>Ctrl+C</code>, 붙여넣기 <code>Ctrl+V</code>, 삭제 <code>Delete</code>, 영구 삭제 <code>Shift+Delete</code> 등)가 여기에 모여 있습니다.</p><ul><li><strong>플러그인별 그룹화</strong>: 제공 플러그인별로 깔끔하게 정리되어 있습니다.</li><li><strong>개별 재등록</strong>: 각 액션마다 전용 녹화 상자가 제공되어 새 키를 입력해 즉시 변경할 수 있습니다.</li></ul><h2 id="_3-프로세스-블랙리스트-process-blacklist" tabindex="-1">3. 프로세스 블랙리스트 (Process Blacklist) <a class="header-anchor" href="#_3-프로세스-블랙리스트-process-blacklist" aria-label="Permalink to &quot;3. 프로세스 블랙리스트 (Process Blacklist)&quot;">​</a></h2><p>특정 프로그램이 활성화되었을 때 Lertaro의 단축키와 마우스 제스처를 무시하도록 설정합니다.</p><ul><li><strong>대소문자 무관</strong>: <code>game.exe</code> 또는 <code>game</code> 모두 지원합니다.</li><li><strong>개별 추가</strong>: 프로세스 이름을 입력하고 <strong>프로세스 추가</strong>를 클릭합니다.</li><li><strong>일괄 관리</strong>: <strong>텍스트 생성</strong>을 눌러 현재 목록을 내보내거나, 붙여넣은 후 <strong>목록에 적용</strong>을 눌러 일괄 갱신할 수 있습니다.</li><li><strong>파일 대화상자 자동 예외</strong>: 블랙리스트 앱이라 하더라도 표준 파일 선택 대화상자가 열리면 인라인 검색 및 퀵 내비게이션이 정상 작동합니다.</li></ul>',16)])])}const p=e(s,[["render",a]]);export{u as __pageData,p as default};
